INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES ("仲間と夏を楽しむ、夏海の魔法士。自分を変えたいという固い決意で、障害物を無効化して走り続ける。", 1, 1, 1.5, 0, 0.029, 122601, 160, 1, 101, 105, 0, 110, 1);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES ("太陽よりも輝く、夏海の元気娘。　持ち前の身体能力で、どんなコースも柔軟に対応し、駆け抜ける。", 0, 2, 2.5, 1, 0.014, 122401, 120, 3, 102, 111, 0, 105, 2);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES ("波打ち際に煌めく、夏海の剣士。　日々の鍛錬で鍛えた脚で、長い距離も速度を落とさず走り切る。", 0, 3, 2.5, 0, 0.017, 122501, 350, 2, 103, 105, 1, 110, 3);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES ("海の幸に目がない、渚のお姫様。　『王家の装備』の力を解放し、障害物をものともせず前へと進む。", 0, 4, 1.5, 1, 0.016, 107501, 130, 3, 104, 105, 0, 110, 4);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES ("海でも主さまをお世話する、白浜の巫女。精霊の力で自身を加速させ、誰よりも速くゴールを目指す。", 1, 5, 2.5, 0, 0.014, 107601, 160, 1, 105, 105, 0, 110, 5);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES ("水着姿を恥じらう、ツンデレ猫娘。お得意の魔法で、対戦相手の走りを妨害し、レースを有利に進める。", 0, 6, 3.5, 0, 0.029, 107801, 255, 2, 106, 103, 1, 120, 6);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES ("優雅に浜を駆ける、真夏のマホ姫。しゃなりしゃなりと、雅な身のこなしで障害物を跳び越えていく。", 1, 7, 3.5, 0, 0.013, 110601, 160, 1, 107, 103, 0, 120, 7);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES ("浜の平和を守る、真夏の狼娘。　　獣人の強靭なスタミナで、レース　後半にスパートをかける。", 0, 8, 2.5, 0, 0.014, 110401, 350, 2, 108, 103, 1, 110, 8);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES ("浜に力強く舞う、真夏の南国娘。　レースの喧噪の中でも精神を乱さず後半に大きな捲りを見せる。", 0, 9, 1.5, 1, 0.012, 110501, 130, 3, 109, 100, 0, 105, 9);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES ("浜の事件を嗅ぎ付けた、真夏の　　名探偵。高い推理力と魔法で、的確に対戦相手の走りを乱す。", 1, 10, 2.5, 0, 0.014, 115701, 200, 1, 110, 103, 0, 105, 10);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES ("再び鎧を脱いだ、灼熱の騎士団長。実戦で培った判断力で、瞬時にバリアを展開し、障害物を無力化する。", 0, 11, 2.5, 0, 0.071, 113601, 350, 2, 111, 103, 1, 105, 11);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES ("水が苦手な、海辺の気まぐれ猫娘。浜に現れた美少女義賊は、対戦相手のスピードを奪いとる。", 0, 12, 1.5, 1, 0.014, 107901, 130, 3, 112, 103, 0, 120, 12);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES ("バカンスも効率第一な、海の傭兵。レースでも最高効率を求め、どんな状況でも隙のない走りを見せる。", 1, 13, 1.5, 0, 0.022, 108001, 200, 2, 113, 105, 0, 110, 13);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES ("真夏の太陽が良く似合う、海辺の　サレンママ。多才で器用、どんな　障害物もエレガントに越えていく。", 1, 14, 2.5, 0, 0.031, 110301, 160, 1, 114, 108, 0, 110, 14);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES ("海に嵐を呼ぶ夏のドジっ娘メイド。日頃から災難に慣れており、多少　のトラブルには動じたりしない。", 0, 15, 0.5, 1, 0.036, 107701, 130, 1, 115, 105, 0, 110, 15);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES ("粋な夏を愉しむ、若夏の姉御。　　流麗な身体捌きで、始・継・終と、UBを重ねるごとに、加速する。", 0, 16, 3.5, 0, 0.048, 113101, 350, 2, 116, 95, 1, 110, 16);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES ("夏のトキメキに触れた、オタク魔法少女。多彩な魔法を操り、少しずつ他の走者の速度を落とし続ける。", 0, 17, 1.5, 1, 0.043, 113301, 130, 3, 117, 105, 0, 105, 17);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES ("海獄に降臨せし、真夏の冥姫。　　レース後半に魔力を全解放し、　　蒼き疾風と成りて浜を駆け抜ける。", 0, 18, 1.5, 1, 0.018, 113201, 130, 2, 118, 95, 0, 105, 18);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES ("夏の夕を火花で彩る、渚の壊し屋。『壊し屋』の異名と過激な愛情は、対戦相手にプレッシャーを与える。", 1, 19, 2.5, 0, 0.021, 117001, 160, 2, 119, 108, 0, 110, 19);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES ("青春に生きる者を導く、夏の先生。夢へと邁進する聖母の加護が、その身をあらゆる困難から守る。", 0, 20, 2.5, 0, 0.036, 113501, 255, 1, 120, 105, 1, 110, 20);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES ("笑顔の応援が眩しい、夏の超能力　ガール。超能力を駆使して、どんな障害物もひとっ飛びで乗り越える。", 0, 21, 2.5, 0, 0.02, 113401, 350, 3, 121, 105, 1, 105, 21);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES ("海辺で大人の魅力を放つ、夏の　　セクシー先生。その魅力に囚われた対戦相手は、走りを乱してしまう。", 0, 22, 2.5, 1, 0.018, 110101, 130, 1, 122, 105, 0, 110, 22);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES ("水着も絶対外さない、夏のカリスマモデル。走りのバイブスは超テンアゲで、スピードはおにやば。", 1, 23, 3.5, 0, 0.03, 110001, 160, 3, 123, 111, 0, 105, 23);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES ("南の島も盛り上げる、真夏のアイドル。悪天候でも笑顔を絶やさず後半もリズムを上げて走り切る。", 0, 24, 1.5, 1, 0.027, 117201, 130, 1, 124, 103, 0, 110, 24);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES ("海原に美声を響かす、渚の歌姫。　守護の賛歌と精霊の加護により、　障害物から身を守る。", 1, 25, 3.5, 0, 0.02, 117301, 160, 2, 125, 108, 0, 105, 25);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES ("夏でも天邪鬼な、夕凪のテーラー。張り巡らされた魔法の糸で、他の走者の自由を奪う。", 0, 26, 2.5, 0, 0.04, 117401, 350, 3, 126, 105, 1, 110, 26);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES ("向日葵が良く似合う、海辺の　　　お姉ちゃん。秘密結社の一員で、　抜群の身体能力が一番の武器。", 0, 27, 3.5, 0, 0.009, 117101, 350, 1, 127, 105, 1, 110, 27);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES ("渚でおっとり、夏色うさぎっこ。　うさぎさんパワー全開で、ぴょん　ぴょんとコースを跳ね回る。", 0, 28, 3.5, 0, 0.022, 122901, 255, 1, 128, 105, 1, 120, 28);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES ("無邪気さ弾ける、夏色いたずら娘。砂浜でも、いたずらの準備は万端！レースに大波乱が巻き起こる！？", 0, 29, 2.5, 1, 0.028, 122801, 130, 3, 129, 105, 0, 110, 29);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES ("海でも真面目な、夏色優等生。　　高めた魔力を解き放ち、一瞬の内に他の走者を置き去りにする。", 1, 30, 3.5, 0, 0.023, 122701, 130, 2, 130, 108, 0, 105, 30);
